/**
 * Fails if the generated output is incomplete.
 *
 * This repository has no test framework, and the cheap failure it kept inviting
 * was a generator that half-ran: Vite bundles fine, one of the four scripts
 * throws or a write is skipped, the build still exits green, and the missing
 * page is only noticed when a link 404s in production. The generators are the
 * test suite here, so this is the assertion that they actually finished.
 *
 * It reads only dist/, so it stays independent of how the pages were produced —
 * a manifest generated by the same script would happily agree with its own
 * mistake.
 *
 * Runs automatically at the end of `npm run build`; can also be run alone as
 * `npm run check:static` after a build.
 */
import { access, readdir, readFile, stat } from 'node:fs/promises';
import { gzipSync } from 'node:zlib';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const dist = path.join(root, 'dist');

// Every route directory carries an index.html and a sibling index.md: the HTML
// is for humans and crawlers, the Markdown is for tools and assistants, and the
// two are written together, so a missing .md means half a route shipped.
const ROOT_FILES = [
  'index.html',
  '404.html',
  'sitemap.xml',
  'robots.txt',
  'rss.xml',
  'llms.txt',
  'manifest.json',
  'sw.js',
  'KashhCMD-Resume.pdf',
  'og-image.jpg',
];
const ROUTE_DIRS = ['journal', 'projects', 'resume', 'uses', 'privacy'];

const failures = [];
const exists = (file) => access(file).then(() => true, () => false);

const requireFile = async (relative) => {
  if (!(await exists(path.join(dist, relative)))) failures.push(`missing ${relative}`);
};

const requireRoute = async (relative) => {
  for (const name of ['index.html', 'index.md']) {
    const file = path.join(dist, relative, name);
    if (!(await exists(file))) {
      failures.push(`missing ${relative}/${name}`);
      continue;
    }
    // A zero-byte file passes a presence-only check and is still a broken route,
    // so the cheapest assertion that it was actually written is that it is not
    // empty.
    if ((await stat(file)).size === 0) failures.push(`empty ${relative}/${name}`);
  }
};

if (!(await exists(dist))) {
  console.error('check-static-output: dist/ not found — run `npm run build` first.');
  process.exit(1);
}

await Promise.all(ROOT_FILES.map(requireFile));
await Promise.all(ROUTE_DIRS.map(requireRoute));

// Each journal entry and project is its own subdirectory, so the set is walked
// from disk rather than from a hardcoded list that would rot the moment a
// project is added.
const manifest = JSON.parse(
  await readFile(path.join(dist, 'manifest.json'), 'utf8').catch(() => '{}')
);
const base = (manifest.start_url ?? '/').replace(/\/$/, '');
// Turns "/portfolio/scriptforge-cover.jpg" into "scriptforge-cover.jpg" without
// assuming the base path, which is the value most likely to change with a host.
const fromSiteRoot = (src) =>
  base && src.startsWith(`${base}/`) ? src.slice(base.length + 1) : src.replace(/^\//, '');

for (const group of ['journal', 'projects']) {
  const dir = path.join(dist, group);
  if (!(await exists(dir))) continue;
  const pages = (await readdir(dir, { withFileTypes: true }))
    .filter((entry) => entry.isDirectory())
    .map((entry) => entry.name);
  if (pages.length === 0) failures.push(`${group}/ has no pages inside it`);
  await Promise.all(pages.map((page) => requireRoute(`${group}/${page}`)));

  // A project without a raster social card shares as a blank rectangle on most
  // platforms; SVG was the specific trap this check exists to keep shut.
  if (group === 'projects') {
    await Promise.all(
      pages.map(async (page) => {
        await requireFile(`og/projects/${page}.jpg`);
        const html = await readFile(path.join(dist, group, page, 'index.html'), 'utf8').catch(
          () => ''
        );
        const image = html.match(/property="og:image" content="([^"]+)"/)?.[1] ?? '';
        if (!image || /\.svg(\?|$)/i.test(image)) {
          failures.push(`projects/${page} has a non-raster og:image`);
        }
        // The page itself embeds the cover as a root-relative banner. The social
        // card can exist while that file is renamed, so resolve it against the
        // manifest's base and assert it landed in dist/.
        const banner = html.match(/<img class="banner" src="([^"]+)"/)?.[1] ?? '';
        if (banner) await requireFile(fromSiteRoot(banner));
      })
    );
  }
}

// llms.txt is a hand-off to anything that reads text rather than HTML, so an
// empty one is a silent failure: the file exists and says nothing.
const llms = await readFile(path.join(dist, 'llms.txt'), 'utf8').catch(() => '');
if (!llms.trim()) failures.push('llms.txt is empty');
for (const group of ROUTE_DIRS) {
  if (llms && !llms.includes(`/${group}/`)) {
    failures.push(`llms.txt does not reference /${group}/`);
  }
}

const robots = await readFile(path.join(dist, 'robots.txt'), 'utf8').catch(() => '');
if (!/^Sitemap:/m.test(robots)) failures.push('robots.txt has no Sitemap line');

// First-paint budget. The journal has a post about cutting 59% of the bundle,
// and without an assertion the next dependency quietly puts it back. The set is
// read from index.html rather than hardcoded, so a vendor chunk added to the
// initial load is measured here without an edit. Lazy chunks — hls, prism and
// the dialogs — are not referenced there and so are deliberately not counted.
const kB = (bytes) => `${(bytes / 1024).toFixed(1)} kB`;
const ENTRY_BUDGET = 50 * 1024;
const CSS_BUDGET = 16 * 1024;
const FIRST_PAINT_BUDGET = 210 * 1024;

const indexHtml = await readFile(path.join(dist, 'index.html'), 'utf8').catch(() => '');
const initialAssets = [
  ...new Set(
    [...indexHtml.matchAll(/(?:src|href)="[^"]*\/assets\/([^"?]+\.(?:js|css))"/g)].map((match) => match[1])
  ),
];

let firstPaint = 0;
for (const asset of initialAssets) {
  const file = path.join(dist, 'assets', asset);
  if (!(await exists(file))) {
    failures.push(`index.html references missing assets/${asset}`);
    continue;
  }
  const size = gzipSync(await readFile(file)).length;
  firstPaint += size;
  if (/^index-.*\.js$/.test(asset) && size > ENTRY_BUDGET) {
    failures.push(`entry JS ${kB(size)} exceeds the ${kB(ENTRY_BUDGET)} budget`);
  }
  if (/^index-.*\.css$/.test(asset) && size > CSS_BUDGET) {
    failures.push(`CSS ${kB(size)} exceeds the ${kB(CSS_BUDGET)} budget`);
  }
}
if (initialAssets.length === 0) failures.push('index.html references no built assets');
if (firstPaint > FIRST_PAINT_BUDGET) {
  failures.push(
    `first paint is ${kB(firstPaint)} gzip, over the ${kB(FIRST_PAINT_BUDGET)} budget`
  );
}

if (failures.length > 0) {
  console.error(`check-static-output: ${failures.length} problem(s) in dist/`);
  for (const failure of failures) console.error(`  - ${failure}`);
  process.exit(1);
}

console.log(
  `check-static-output: dist/ is complete (first paint ${kB(firstPaint)} gzip, budget ${kB(FIRST_PAINT_BUDGET)}).`
);
